package main

func runDepsCommand(args []string) {
    fs := flag.NewFlagSet("deps", flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    configPath := fs.String("config", "", "path to TOML pipeline file")
    why := fs.Bool("why", false, "show dependency paths from one target to another")
    affected := fs.Bool("affected", false, "show rebuild order for affected files")
    plan := fs.Bool("plan", false, "with --affected, output parallel rebuild layers")
    var vars stringSliceFlag
    fs.Var(&vars, "var", "variable override key=value (repeatable)")
    if err := fs.Parse(args); err != nil {
        os.Exit(1)
    }
    if *configPath == "" {
        fmt.Fprintln(os.Stderr, "error: --config is required")
        os.Exit(1)
    }
    if *plan && !*affected {
        fmt.Fprintln(os.Stderr, "error: --plan requires --affected")
        os.Exit(1)
    }
    if err := runDeps(*configPath, []string(vars), fs.Args(), *why, *affected, *plan); err != nil {
        fmt.Fprintln(os.Stderr, err)
        os.Exit(1)
    }
}

func runDeps(configPath string, vars []string, args []string, why, affected, plan bool) error {
    cfg, _, err := loadConfig(configPath, vars)
    if err != nil {
        return err
    }
    targetMap, err := validateConfig(cfg)
    if err != nil {
        return err
    }

    if affected {
        if len(args) == 0 {
            return fmt.Errorf("--affected requires at least one FILE")
        }
        return runDepsAffected(cfg, targetMap, args, plan)
    }

    if why {
        if len(args) != 2 {
            return fmt.Errorf("--why requires exactly two target names: FROM TO")
        }
        return runDepsWhy(cfg, targetMap, args[0], args[1])
    }

    if len(args) != 1 {
        return fmt.Errorf("deps requires exactly one target name")
    }
    return runDepsTarget(cfg, targetMap, args[0])
}

func runDepsTarget(cfg *Config, targetMap map[string]*TargetConfig, target string) error {
    if _, ok := targetMap[target]; !ok {
        failDepsJSON(fmt.Sprintf("target %q does not exist", target))
        return nil
    }

    directSet := map[string]bool{}
    for _, dep := range uniqueStrings(targetMap[target].Dependencies) {
        directSet[dep] = true
    }
    direct := sortedKeys(directSet)

    transitiveSet := map[string]bool{}
    collectTransitiveDeps(targetMap, target, transitiveSet)
    delete(transitiveSet, target)
    transitive := sortedKeys(transitiveSet)

    reverseSet := map[string]bool{}
    for _, t := range cfg.Targets {
        if t.Name == target {
            continue
        }
        seen := map[string]bool{}
        if dependsOnTransitive(targetMap, t.Name, target, seen) {
            reverseSet[t.Name] = true
        }
    }
    reverse := sortedKeys(reverseSet)

    return emitJSON(map[string]interface{}{
        "target":          target,
        "direct_deps":     direct,
        "transitive_deps": transitive,
        "reverse_deps":    reverse,
    })
}

func runDepsWhy(cfg *Config, targetMap map[string]*TargetConfig, from, to string) error {
    if _, ok := targetMap[from]; !ok {
        failDepsJSON(fmt.Sprintf("target %q does not exist", from))
        return nil
    }
    if _, ok := targetMap[to]; !ok {
        failDepsJSON(fmt.Sprintf("target %q does not exist", to))
        return nil
    }

    paths := allDependencyPaths(targetMap, from, to)
    sortPaths(paths)
    return emitJSON(map[string]interface{}{
        "from":  from,
        "to":    to,
        "paths": paths,
    })
}

func runDepsAffected(cfg *Config, targetMap map[string]*TargetConfig, files []string, plan bool) error {
    fileSet := map[string]bool{}
    for _, f := range files {
        fileSet[f] = true
    }

    affectedSet := map[string]bool{}
    directAffected := map[string]bool{}
    for i := range cfg.Targets {
        t := &cfg.Targets[i]
        for _, input := range t.Inputs {
            if fileSet[input] {
                affectedSet[t.Name] = true
                directAffected[t.Name] = true
                break
            }
        }
    }

    // Include targets that transitively depend on directly affected targets.
    queue := sortedKeys(affectedSet)
    for len(queue) > 0 {
        name := queue[0]
        queue = queue[1:]
        for _, t := range cfg.Targets {
            if affectedSet[t.Name] {
                continue
            }
            for _, dep := range uniqueStrings(t.Dependencies) {
                if dep == name {
                    affectedSet[t.Name] = true
                    queue = append(queue, t.Name)
                    break
                }
            }
        }
    }

    if len(affectedSet) == 0 {
        if plan {
            return emitJSON(map[string]interface{}{"rebuild_plan": []interface{}{}})
        }
        return emitJSON(map[string]interface{}{"rebuild_order": []interface{}{}})
    }

    if plan {
        layers := buildRebuildLayers(targetMap, affectedSet, directAffected)
        return emitJSON(map[string]interface{}{"rebuild_plan": layers})
    }

    order := topologicalOrderSubset(cfg, affectedSet)
    entries := []map[string]interface{}{}
    for _, name := range order {
        entries = append(entries, map[string]interface{}{
            "target": name,
            "direct": directAffected[name],
        })
    }
    return emitJSON(map[string]interface{}{"rebuild_order": entries})
}

func collectTransitiveDeps(targetMap map[string]*TargetConfig, name string, seen map[string]bool) {
    for _, dep := range uniqueStrings(targetMap[name].Dependencies) {
        if !seen[dep] {
            seen[dep] = true
            collectTransitiveDeps(targetMap, dep, seen)
        }
    }
}

func dependsOnTransitive(targetMap map[string]*TargetConfig, name, target string, seen map[string]bool) bool {
    if seen[name] {
        return false
    }
    seen[name] = true
    for _, dep := range uniqueStrings(targetMap[name].Dependencies) {
        if dep == target {
            return true
        }
        if dependsOnTransitive(targetMap, dep, target, seen) {
            return true
        }
    }
    return false
}

func allDependencyPaths(targetMap map[string]*TargetConfig, from, to string) [][]string {
    var paths [][]string
    var current []string
    visited := map[string]bool{}
    var dfs func(node string)
    dfs = func(node string) {
        if visited[node] {
            return
        }
        current = append(current, node)
        visited[node] = true

        if node == to && len(current) > 1 {
            path := make([]string, len(current))
            copy(path, current)
            paths = append(paths, path)
        } else if node != to {
            for _, dep := range uniqueStrings(targetMap[node].Dependencies) {
                dfs(dep)
            }
        }

        current = current[:len(current)-1]
        delete(visited, node)
    }
    dfs(from)
    return paths
}

func sortPaths(paths [][]string) {
    sort.Slice(paths, func(i, j int) bool {
        if len(paths[i]) != len(paths[j]) {
            return len(paths[i]) < len(paths[j])
        }
        for k := 0; k < len(paths[i]) && k < len(paths[j]); k++ {
            if paths[i][k] != paths[j][k] {
                return paths[i][k] < paths[j][k]
            }
        }
        return false
    })
}

func topologicalOrderSubset(cfg *Config, subset map[string]bool) []string {
    indeg := map[string]int{}
    for name := range subset {
        indeg[name] = 0
    }
    for _, t := range cfg.Targets {
        if !subset[t.Name] {
            continue
        }
        for _, dep := range uniqueStrings(t.Dependencies) {
            if subset[dep] {
                indeg[t.Name]++
            }
        }
    }

    queue := []string{}
    for name := range subset {
        if indeg[name] == 0 {
            queue = append(queue, name)
        }
    }
    sort.Strings(queue)

    order := []string{}
    for len(queue) > 0 {
        name := queue[0]
        queue = queue[1:]
        order = append(order, name)

        for _, t := range cfg.Targets {
            if !subset[t.Name] {
                continue
            }
            for _, dep := range uniqueStrings(t.Dependencies) {
                if dep == name {
                    indeg[t.Name]--
                    if indeg[t.Name] == 0 {
                        queue = append(queue, t.Name)
                    }
                    break
                }
            }
        }
        sort.Strings(queue)
    }
    return order
}

