            }
            for _, dep := range uniqueStrings(t.Dependencies) {
                if dep == name {
                    indeg[t.Name]--
                    if indeg[t.Name] == 0 {
                        queue = append(queue, t.Name)
                    }
                    break
                }
            }
        }
        sort.Strings(queue)
    }
    return order
}

